def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_prev = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if bid >= 100:
                    dangerous_prev.append(bid)

    if not alive:
        base = 18.0 if hp > 3 else 35.0
        return max(0.0, min(budget, base))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgent = hp <= 2 or no_water >= 1
    very_urgent = hp <= 1 or no_water >= 2

    if very_urgent:
        bid = max(90.0, highest_prev + 3.0)
        return max(0.0, min(budget, bid))

    if urgent:
        bid = 62.0 + 28.0 * scarcity
        if highest_prev > 0:
            bid = max(bid, min(highest_prev + 2.0, 115.0))
        return max(0.0, min(budget, bid))

    if supply >= 22:
        if dangerous_prev:
            bid = 16.0
        else:
            bid = max(20.0, avg_prev * 0.45)
        return max(0.0, min(budget, bid))

    if supply <= 17:
        target = 48.0 + 22.0 * scarcity
        if highest_prev > 0:
            if highest_prev <= 85.0:
                target = max(target, highest_prev + 1.5)
            else:
                target = max(42.0, highest_prev * 0.72)
        if budget < DAILY_SALARY * 2:
            target *= 0.9
        return max(0.0, min(budget, target))

    target = 34.0 + 18.0 * scarcity
    if highest_prev > 0:
        if highest_prev < 70.0:
            target = max(target, highest_prev + 1.2)
        elif highest_prev > 120.0:
            target = min(target, 46.0)
        else:
            target = max(target, highest_prev * 0.6)

    if day >= 8 and hp >= 4:
        target *= 0.9
    if budget < 140:
        target *= 0.88

    return max(0.0, min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = day_context['day']

    # Collect alive opponents and their yesterday bids
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        # No one to contest; bid conservatively
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Determine pressure from yesterday
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    # Also detect if a specific opponent was very aggressive yesterday (likely Cindy)
    aggressive_prev = False
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is None:
            continue
        try:
            if float(b) >= 0.9 * highest_prev_bid and float(b) >= DAILY_SALARY * 1.0:
                aggressive_prev = True
                break
        except Exception:
            continue

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status.get('no_water_days', 0) or 0)

    # Base strategy: secure water when at risk; otherwise avoid overpaying.
    # If we are already low HP or have gone multiple no-water days, bid closer to aggressive pressure.
    risk_factor = 0.0
    if hp <= 2.0:
        risk_factor += 1.0
    if hp <= 4.0:
        risk_factor += 0.6
    if no_water_days >= 2:
        risk_factor += 0.8
    if no_water_days >= 3:
        risk_factor += 1.0

    # Supply level affects how many units could be won; with higher supply we can bid less.
    # Use integer index safety for any derived bins.
    supply_bin = int((supply - MIN_SUPPLY) / max(1.0, (MAX_SUPPLY - MIN_SUPPLY)) * 2)  # 0..2
    if supply_bin < 0:
        supply_bin = 0
    if supply_bin > 2:
        supply_bin = 2

    # Target bid multiplier table by supply_bin (lower supply => bid more)
    mult_table = [1.05, 0.95, 0.85]
    mult = float(mult_table[supply_bin])

    # If Cindy-like aggression exists, we slightly undercut relative to highest_prev_bid.
    # Otherwise bid around a moderate fraction of daily salary.
    if aggressive_prev and highest_prev_bid > 0:
        # Undercut by a small margin; if we're in danger, close the gap.
        undercut = 12.0
        if risk_factor >= 1.0:
            undercut = 6.0
        if risk_factor >= 1.6:
            undercut = 2.0
        target = highest_prev_bid * mult - undercut
    else:
        target = DAILY_SALARY * (0.55 + 0.25 * risk_factor) * mult

    # Ensure we don't bid more than budget and keep non-negative
    if target < 0:
        target = 0.0

    # If our hp is very low, we must bid high to survive
    if hp <= 1.5:
        target = max(target, DAILY_SALARY * 0.95)
    elif hp <= 3.0:
        target = max(target, DAILY_SALARY * 0.75)

    # If we have lots of budget and mid/high hp, avoid unnecessary overbids
    if hp >= 7.0 and budget > DAILY_SALARY * 3:
        target = min(target, DAILY_SALARY * 0.65)

    bid = float(min(budget, target))

    # Small day-based adjustment: later days require more water.
    # Episode length is 10; day ranges likely 1..10.
    if day >= 8:
        bid = min(budget, bid * 1.1)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Base bid proportional to water need relative to supply
    base_bid = (WATER_REQ / supply) * DAILY_SALARY * 1.2
    # Adjust for hp
    if hp <= 3:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)
    if no_water_days > 0:
        base_bid = max(base_bid, DAILY_SALARY * 0.7)

    # Look at yesterday's max bid from opponents
    max_prev_bid = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            if prev['bid'] > max_prev_bid:
                max_prev_bid = prev['bid']

    # If opponents were aggressive, we need to compete
    if max_prev_bid > DAILY_SALARY * 1.0:
        # highly aggressive opponent
        if hp <= 2:
            target = max(DAILY_SALARY * 1.2, max_prev_bid + 1)
        else:
            target = min(DAILY_SALARY * 0.8, max_prev_bid - 10)
    elif max_prev_bid > DAILY_SALARY * 0.6:
        target = max(base_bid, max_prev_bid + 2)
    else:
        target = base_bid

    # ensure within budget and not too high
    final_bid = min(budget, max(0, target))
    return int(final_bid)
